    const nav = document.querySelector('.nav-v3');
    if (!nav) return;

    const burgerBtn = nav.querySelector('.nav-burger-menu');
    const navCont = nav.querySelector('.nav-v3-cont');
    const mask = nav.querySelector('.nav-dropdown_mask');
    const registerBtn = nav.querySelector('.button-4');
    const navOverlay = nav.querySelector('.overlay-40');
    const logoLink = nav.querySelector('.nav-v3-logo')?.closest('a');
    if (!burgerBtn || !navCont || !mask) return;

    const rects = burgerBtn.querySelectorAll('rect');
    const rectTop = rects[0];
    const rectMid = rects[1];
    const rectBot = rects[2];

    const tl = gsap.timeline({
      paused: true,
      defaults: { duration: 0.45, ease: 'power3.inOut' }
    });

    tl.to(navCont, { backgroundColor: '#000000' }, 0)
